  const c=host.context(),b=a.buffer,n=b.length,sr=b.sampleRate,f=R.clean(t.klfx),k=Math.round(n*f.flytt/16),i0=Math.round(s.a*n),i1=Math.round(s.b*n),fade=Math.round(sr*.004);
  let out=[];for(let ch=0;ch<b.numberOfChannels;ch++){const x=b.getChannelData(ch),y=new Float32Array(n);if(k){y.set(x.subarray(n-k),0);y.set(x.subarray(0,n-k),k)}else y.set(x);out.push(y)}
  let cuts=a.cuts.slice(),bars=a.bars,msg;
