  b.onpointerup=e=>endKey(e.pointerId);b.onpointercancel=e=>endKey(e.pointerId);b.onlostpointercapture=e=>endKey(e.pointerId);
  b.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.repeat){e.preventDefault();preview(pitch(b),'button')}};
